const MAIN_BYTES:u64=8*1024*1024;
const PAYLOAD_BYTES:i64=3*1024*1024;
fn sql(e:rusqlite::Error)->Error { let code=match e.sqlite_error_code(){Some(rusqlite::ErrorCode::DatabaseBusy|rusqlite::ErrorCode::DatabaseLocked)=>"OC_EVENT_LOCKED",Some(rusqlite::ErrorCode::OperationInterrupted)=>"ETIMEDOUT",Some(rusqlite::ErrorCode::DiskFull)=>"OC_EVENT_FULL",Some(rusqlite::ErrorCode::OutOfMemory|rusqlite::ErrorCode::TooBig)=>"OC_EVENT_LIMIT",_=>"OC_EVENT_DATABASE"}; Error::new(code,"事件数据库操作失败 / Event database operation failed") }
fn invalid()->Error {Error::invalid("event worker request")}
fn encode<T:serde::Serialize>(v:T)->Result<Value>{serde_json::to_value(v).map_err(|_|invalid())}
fn close_file(file:File)->Result<()> {let fd=file.into_raw_fd();if unsafe{libc::close(fd)}==0{Ok(())}else{Err(Error::cleanup("event file",Error::io("close",std::io::Error::last_os_error())))}}
fn safe(path:&Path,directory:bool)->Result<fs::Metadata>{let m=fs::symlink_metadata(path).map_err(|e|Error::io("stat event path",e))?; if m.file_type().is_symlink() || (if directory {!m.is_dir()}else{!m.is_file()||m.nlink()!=1}) || m.uid()!=unsafe{libc::geteuid()} || m.mode()&0o777 != if directory{0o700}else{0o600}{return Err(Error::new("OC_EVENT_PERMISSION","事件数据路径必须私有且非链接 / Event path must be private and not linked"));}Ok(m)}
fn identity(path:&Path)->Result<(u64,u64)>{let m=fs::symlink_metadata(path).map_err(|e|Error::io("stat database",e))?;if !m.is_file()||m.file_type().is_symlink(){return Err(Error::invalid("database identity"));}Ok((m.dev(),m.ino()))}
fn verify(path:&Path,id:(u64,u64))->Result<()> {if identity(path)?!=id {Err(Error::new("OC_COLLECTION_CHANGED","数据库身份已改变 / Database identity changed"))}else{Ok(())}}
