    let request=match operation{"events-load"=>Request::Load(serde_json::from_value(input).map_err(|_|invalid())?),"events-commit"=>Request::Commit(serde_json::from_value(input).map_err(|_|invalid())?),"events-query"=>Request::Query(serde_json::from_value(input).map_err(|_|invalid())?),_=>return Err(invalid())};
