fn journal(operation:&str,path:&Path,input:Value)->Result<Value>{
    use crate::events::journal::Journal;
    if operation=="events-journal-read" {
        if input!=json!({}){return Err(invalid());}
        let parent=path.parent().ok_or_else(invalid)?;
        match fs::symlink_metadata(parent){Err(e) if e.kind()==std::io::ErrorKind::NotFound=>return encode(Journal::default()),Err(e)=>return Err(Error::io("notification directory",e)),Ok(_)=>{safe(parent,true)?;}}
        match fs::symlink_metadata(path){Err(e) if e.kind()==std::io::ErrorKind::NotFound=>return encode(Journal::default()),Err(e)=>return Err(Error::io("notification journal",e)),Ok(_)=>{}}
        let metadata=safe(path,false)?;if metadata.len()>65536{return Err(Error::limit("notification journal bytes",65536,metadata.len() as usize));}
        let mut file=OpenOptions::new().read(true).custom_flags(libc::O_NOFOLLOW|libc::O_NONBLOCK).open(path).map_err(|e|Error::io("open notification journal",e))?;
        let result=(||{let actual=file.metadata().map_err(|e|Error::io("stat notification journal",e))?;if stamp(&actual)!=stamp(&metadata){return Err(invalid());}let mut bytes=Vec::with_capacity(metadata.len() as usize);(&mut file).take(65537).read_to_end(&mut bytes).map_err(|e|Error::io("read notification journal",e))?;if bytes.len()>65536{return Err(invalid());}let after=file.metadata().map_err(|e|Error::io("stat notification journal after read",e))?;if stamp(&after)!=stamp(&metadata)||stamp(&safe(path,false)?)!=stamp(&metadata){return Err(Error::new("OC_COLLECTION_CHANGED","通知日志读取期间变化 / Notification journal changed while reading"));}let journal:Journal=serde_json::from_slice(&bytes).map_err(|_|invalid())?;journal.validate()?;encode(journal)})();return crate::io::merge_close(result,close_file(file));
    }
    let value:Journal=serde_json::from_value(input).map_err(|_|invalid())?;value.validate()?;let bytes=serde_json::to_vec(&value).map_err(|_|invalid())?;if bytes.len()>65536{return Err(invalid());}
    journal_write_bytes(path,&bytes)?;Ok(Value::Null)
}

